import * as THREE from 'three';
import { createScene } from './object.js';
import * as fs from 'fs';
import * as path from 'path';

// OBJ Exporter implementation
class OBJExporter {
  parse(object) {
    let output = '';
    let indexVertex = 0;
    let indexNormals = 0;

    const vertex = new THREE.Vector3();
    const normal = new THREE.Vector3();
    const normalMatrixWorld = new THREE.Matrix3();

    // Traverse all meshes and collect geometry
    output += '# OBJ file exported from Three.js\n';
    output += '# Converted to Blender Z-up coordinate system\n\n';

    const parseMesh = (mesh) => {
      let nbVertex = 0;
      let nbNormals = 0;

      const geometry = mesh.geometry;
      if (!geometry || !geometry.isBufferGeometry) return;

      // Get world matrix for this mesh
      const matrixWorld = mesh.matrixWorld;
      normalMatrixWorld.getNormalMatrix(matrixWorld);

      // Handle indexed and non-indexed geometry
      const vertices = geometry.getAttribute('position');
      const normals = geometry.getAttribute('normal');
      const indices = geometry.getIndex();

      if (!vertices) return;

      // Output object name
      output += 'o ' + (mesh.name || 'mesh') + '\n';

      // Write vertices
      for (let i = 0; i < vertices.count; i++) {
        vertex.set(vertices.getX(i), vertices.getY(i), vertices.getZ(i));
        vertex.applyMatrix4(matrixWorld);
        output += 'v ' + vertex.x.toFixed(6) + ' ' + vertex.y.toFixed(6) + ' ' + vertex.z.toFixed(6) + '\n';
        nbVertex++;
      }

      // Write normals
      if (normals) {
        for (let i = 0; i < normals.count; i++) {
          normal.set(normals.getX(i), normals.getY(i), normals.getZ(i));
          normal.applyMatrix3(normalMatrixWorld).normalize();
          output += 'vn ' + normal.x.toFixed(6) + ' ' + normal.y.toFixed(6) + ' ' + normal.z.toFixed(6) + '\n';
          nbNormals++;
        }
      }

      // Write faces
      if (indices) {
        for (let i = 0; i < indices.count; i += 3) {
          const a = indices.getX(i) + 1 + indexVertex;
          const b = indices.getX(i + 1) + 1 + indexVertex;
          const c = indices.getX(i + 2) + 1 + indexVertex;

          if (normals) {
            const na = indices.getX(i) + 1 + indexNormals;
            const nb = indices.getX(i + 1) + 1 + indexNormals;
            const nc = indices.getX(i + 2) + 1 + indexNormals;
            output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
          } else {
            output += 'f ' + a + ' ' + b + ' ' + c + '\n';
          }
        }
      } else {
        // Non-indexed geometry
        for (let i = 0; i < vertices.count; i += 3) {
          const a = i + 1 + indexVertex;
          const b = i + 2 + indexVertex;
          const c = i + 3 + indexVertex;

          if (normals) {
            const na = i + 1 + indexNormals;
            const nb = i + 2 + indexNormals;
            const nc = i + 3 + indexNormals;
            output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
          } else {
            output += 'f ' + a + ' ' + b + ' ' + c + '\n';
          }
        }
      }

      output += '\n';
      indexVertex += nbVertex;
      indexNormals += nbNormals;
    };

    // Handle InstancedMesh by expanding instances
    const parseInstancedMesh = (mesh) => {
      const geometry = mesh.geometry;
      if (!geometry || !geometry.isBufferGeometry) return;

      const count = mesh.count;
      const instanceMatrix = new THREE.Matrix4();

      for (let instanceIndex = 0; instanceIndex < count; instanceIndex++) {
        mesh.getMatrixAt(instanceIndex, instanceMatrix);

        // Combine instance matrix with world matrix
        const combinedMatrix = mesh.matrixWorld.clone().multiply(instanceMatrix);

        let nbVertex = 0;
        let nbNormals = 0;

        const vertices = geometry.getAttribute('position');
        const normals = geometry.getAttribute('normal');
        const indices = geometry.getIndex();

        if (!vertices) continue;

        normalMatrixWorld.getNormalMatrix(combinedMatrix);

        // Output object name
        output += 'o ' + (mesh.name || 'mesh') + '_instance_' + instanceIndex + '\n';

        // Write vertices
        for (let i = 0; i < vertices.count; i++) {
          vertex.set(vertices.getX(i), vertices.getY(i), vertices.getZ(i));
          vertex.applyMatrix4(combinedMatrix);
          output += 'v ' + vertex.x.toFixed(6) + ' ' + vertex.y.toFixed(6) + ' ' + vertex.z.toFixed(6) + '\n';
          nbVertex++;
        }

        // Write normals
        if (normals) {
          for (let i = 0; i < normals.count; i++) {
            normal.set(normals.getX(i), normals.getY(i), normals.getZ(i));
            normal.applyMatrix3(normalMatrixWorld).normalize();
            output += 'vn ' + normal.x.toFixed(6) + ' ' + normal.y.toFixed(6) + ' ' + normal.z.toFixed(6) + '\n';
            nbNormals++;
          }
        }

        // Write faces
        if (indices) {
          for (let i = 0; i < indices.count; i += 3) {
            const a = indices.getX(i) + 1 + indexVertex;
            const b = indices.getX(i + 1) + 1 + indexVertex;
            const c = indices.getX(i + 2) + 1 + indexVertex;

            if (normals) {
              const na = indices.getX(i) + 1 + indexNormals;
              const nb = indices.getX(i + 1) + 1 + indexNormals;
              const nc = indices.getX(i + 2) + 1 + indexNormals;
              output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
            } else {
              output += 'f ' + a + ' ' + b + ' ' + c + '\n';
            }
          }
        } else {
          for (let i = 0; i < vertices.count; i += 3) {
            const a = i + 1 + indexVertex;
            const b = i + 2 + indexVertex;
            const c = i + 3 + indexVertex;

            if (normals) {
              const na = i + 1 + indexNormals;
              const nb = i + 2 + indexNormals;
              const nc = i + 3 + indexNormals;
              output += 'f ' + a + '//' + na + ' ' + b + '//' + nb + ' ' + c + '//' + nc + '\n';
            } else {
              output += 'f ' + a + ' ' + b + ' ' + c + '\n';
            }
          }
        }

        output += '\n';
        indexVertex += nbVertex;
        indexNormals += nbNormals;
      }
    };

    // Update world matrices
    object.updateMatrixWorld(true);

    // Traverse and parse all meshes
    object.traverse((child) => {
      if (child.isInstancedMesh) {
        parseInstancedMesh(child);
      } else if (child.isMesh) {
        parseMesh(child);
      }
    });

    return output;
  }
}

// Main export function
function exportToOBJ() {
  // Create the scene from the input file
  const root = createScene();

  // Apply -90 degree X rotation to convert from Three.js Y-up to Blender Z-up
  // In Three.js, Y is up. In Blender, Z is up.
  // Rotating -90 degrees around X axis: Y becomes Z, Z becomes -Y
  const rotationX = -Math.PI / 2; // -90 degrees in radians
  root.rotation.x = rotationX;

  // Update world matrices after rotation
  root.updateMatrixWorld(true);

  // Create exporter and export
  const exporter = new OBJExporter();
  const objContent = exporter.parse(root);

  // Write to output file
  const outputPath = '/root/output/object.obj';
  fs.writeFileSync(outputPath, objContent);

  console.log('Successfully exported to:', outputPath);
  console.log('Applied -90 degree X rotation for Blender Z-up coordinate system');
}

// Run the export
exportToOBJ();

